Given a matrix mat[][] of dimensions N * M, the task is to sort each column of a matrix in ascending order and print the updated matrix.



Examples:



Input: mat[][] = { {1, 6, 10}, {8, 5, 9}, {9, 4, 15}, {7, 3, 60} }Output:1 3 97 4 108 5 159 6 60Explanation:The input matrix is sorted in a column wise manner,  1 < 7 < 8 < 93 < 4 < 5 < 69 < 10 < 15 < 60



Input: arr[][] = { {1, 6}, {8, 4}, {9, 7} }Output:1 48 69 7



Approach: Follow the steps below to solve the problem:

Traverse the matrixFind the transpose of the given matrix mat[][].Store this transpose of mat[][] in a 2D vector, tr[][]Traverse the rows of the matrix tr[][]Sort each row of the matrix using the sort function.Store the transpose of tr[][] in mat[][]Print the matrix, mat[][]

Below is the implementation of the above approach:



            C++

    // C++ program for the above approach

#include <bits/stdc++.h>
using namespace std;

// Function to find the transpose
// of the matrix mat[]
vector<vector<int> > transpose(
    vector<vector<int> > mat,
    int row, int col)
{

    // Stores the transpose
    // of matrix mat[][]
    vector<vector<int> > tr(
        col, vector<int>(row));

    // Traverse each row of the matrix
    for (int i = 0; i < row; i++) {

        // Traverse each column of the matrix
        for (int j = 0; j < col; j++) {

            // Transpose matrix elements
            tr[j][i] = mat[i][j];
        }
    }

    return tr;
}

// Function to sort the given
// matrix in row wise manner
void RowWiseSort(vector<vector<int> >& B)
{
    // Traverse the row
    for (int i = 0; i < (int)B.size(); i++) {

        // Row - Wise Sorting
        sort(B[i].begin(), B[i].end());
    }
}

// Function to print the matrix
// in column wise sorted manner
void sortCol(vector<vector<int> > mat,
             int N, int M)
{
    // Function call to find transpose
    // of the matrix mat[][]
    vector<vector<int> > B
        = transpose(mat, N, M);

    // Sorting the matrix row-wise
    RowWiseSort(B);

    // Calculate transpose of B[][]
    mat = transpose(B, M, N);

    // Print the matrix mat[][]
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {

            cout << mat[i][j] << " ";
        }
        cout << '\n';
    }
}

// Driver Code
int main()
{
    // Input
    vector<vector<int> > mat = { { 1, 6, 10 },
                                 { 8, 5, 9 },
                                 { 9, 4, 15 },
                                 { 7, 3, 60 } };

    int N = mat.size();
    int M = mat[0].size();

    // Function call to print the matrix
    // in column wise sorted manner
    sortCol(mat, N, M);

    return 0;
}


